package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0           // PIC 9(3) len=3 = 0
var WsR100 int64 = 0         // PIC 9(3) len=3 = 0
var WsR400 int64 = 0         // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0       // PIC 99 len=2 = 0
var WsValid int64 = 0        // PIC 99 len=2 = 0
var WsBadMonth int64 = 0     // PIC 99 len=2 = 0
var WsBadDay int64 = 0       // PIC 99 len=2 = 0

var DateRecData DateRec

var dateFileScanner *bufio.Scanner
var dateFileHandle *os.File

var WsIsLeap = func() bool { return WsLeapFlag == "Y" }
var WsInputDone = func() bool { return WsEofFlag == "Y" }

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func trunc(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := pow10(digits)
	// keep low-order digits, handle negative? COBOL would preserve sign? But values are positive.
	// For negative, Go % gives negative remainder, adjust to keep truncation semantics.
	// We'll implement positive modulo for negative as well (low-order digits of absolute).
	if v < 0 {
		// COBOL moves would keep sign? But not needed here.
		av := -v
		av = av % mod
		return -av
	}
	return v % mod
}

func formatNumeric(v int64, digits int) string {
	mod := pow10(digits)
	// for display, high-order digits dropped
	// ensure positive representation like COBOL: if negative, maybe sign? Not needed.
	if v < 0 {
		v = -v
		v = v % mod
		// COBOL would show sign? But not required for this program.
		return fmt.Sprintf("%0*d", digits, v)
	}
	v = v % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func parseNum(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// COBOL numeric fields contain digits only; if contains spaces/pads, we trimmed.
	// Take only leading digits? Use general parse.
	// Remove any non-digit? But spec says digits.
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// if parse fails, extract digits
		var digits strings.Builder
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				digits.WriteRune(ch)
			}
		}
		if digits.Len() == 0 {
			return 0
		}
		v2, _ := strconv.ParseInt(digits.String(), 10, 64)
		return v2
	}
	return v
}

func isLeapFlag() bool {
	return WsLeapFlag == "Y"
}

// prevent unused import error for decimal
var _ = decimal.NewFromInt

func MAINPARA() {
	// OPEN INPUT DATE-FILE
	var err error
	dateFileHandle, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as EOF (COBOL would error, but we set done)
		WsEofFlag = "Y"
	} else {
		dateFileScanner = bufio.NewScanner(dateFileHandle)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		dateFileScanner.Buffer(buf, 1024*1024)
	}
	READPARA()
	for !WsInputDone() {
		PROCESSPARA()
	}
	if dateFileHandle != nil {
		dateFileHandle.Close()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Println("VALID: "+formatNumeric(WsValid, 2)+" BAD MONTH: "+formatNumeric(WsBadMonth, 2)+" BAD DAY: "+formatNumeric(WsBadDay, 2))
}

func READPARA() {
	if dateFileScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !dateFileScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := dateFileScanner.Text()
	// strip trailing \r if any (scanner strips \n, but \r remains for Windows)
	// Actually scanner with default split will keep \r? Input is LINE SEQUENTIAL, lines delimited by newline. We'll handle.
	if len(line) > 0 && line[len(line)-1] == '\r' {
		line = line[:len(line)-1]
	}
	// pad with spaces to 12 on right if shorter
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	// parse record
	DateRecData.DtId = line[0:4]
	DateRecData.DtYyyy = trunc(parseNum(line[4:8]), 4)
	DateRecData.DtMm = trunc(parseNum(line[8:10]), 2)
	DateRecData.DtDd = trunc(parseNum(line[10:12]), 2)
}

func PROCESSPARA() {
	LEAPPARA()
	// EVALUATE TRUE
	if DateRecData.DtMm < 1 || DateRecData.DtMm > 12 {
		WsBadMonth = trunc(WsBadMonth+1, 2)
		fmt.Println(DateRecData.DtId + " BAD MONTH " + formatNumeric(DateRecData.DtMm, 2))
	} else {
		DAYSPARA()
		if DateRecData.DtDd < 1 || DateRecData.DtDd > WsMaxDay {
			WsBadDay = trunc(WsBadDay+1, 2)
			fmt.Println(DateRecData.DtId + " BAD DAY " + formatNumeric(DateRecData.DtDd, 2) + " MAX " + formatNumeric(WsMaxDay, 2))
		} else {
			WsValid = trunc(WsValid+1, 2)
			fmt.Println(DateRecData.DtId + " VALID " + formatNumeric(DateRecData.DtYyyy, 4) + "-" + formatNumeric(DateRecData.DtMm, 2) + "-" + formatNumeric(DateRecData.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// etc.
	// integer division
	WsQ = trunc(DateRecData.DtYyyy/4, 4)
	WsR4 = trunc(DateRecData.DtYyyy%4, 3)
	WsQ = trunc(DateRecData.DtYyyy/100, 4)
	WsR100 = trunc(DateRecData.DtYyyy%100, 3)
	WsQ = trunc(DateRecData.DtYyyy/400, 4)
	WsR400 = trunc(DateRecData.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch DateRecData.DtMm {
	case 2:
		if isLeapFlag() {
			WsMaxDay = trunc(29, 2)
		} else {
			WsMaxDay = trunc(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = trunc(30, 2)
	default:
		WsMaxDay = trunc(31, 2)
	}
}

func main() {
	MAINPARA()
}
